-- V1__create_tables.sql

-- One-to-Many / Many-to-One: one account has many transactions.
CREATE TABLE accounts (
    id          VARCHAR(20) PRIMARY KEY,
    holder_name VARCHAR(100) NOT NULL
);
CREATE TABLE transactions (
    txn_id     VARCHAR(24) PRIMARY KEY,
    account_id VARCHAR(20) NOT NULL REFERENCES accounts(id),  -- FK on the MANY side
    amount     DECIMAL(15,2) NOT NULL
);
CREATE INDEX idx_txn_account ON transactions(account_id);

-- One-to-One: each account has exactly one KYC record (unique FK = account id).
CREATE TABLE account_kyc (
    account_id VARCHAR(20) PRIMARY KEY REFERENCES accounts(id),  -- shared PK = 1:1
    aadhaar    CHAR(12) NOT NULL,
    verified   BOOLEAN  NOT NULL DEFAULT FALSE
);

-- Many-to-Many: customers hold many products; products held by many customers.
CREATE TABLE customers (
    customer_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    full_name   VARCHAR(100) NOT NULL
);
CREATE TABLE products (
    product_id  VARCHAR(20) PRIMARY KEY,
    name        VARCHAR(60) NOT NULL
);
CREATE TABLE holdings (                                   -- junction / bridge table
    customer_id BIGINT      NOT NULL REFERENCES customers(customer_id),
    product_id  VARCHAR(20) NOT NULL REFERENCES products(product_id),
    acquired_on DATE        NOT NULL DEFAULT CURRENT_DATE, -- attribute of the relationship
    PRIMARY KEY (customer_id, product_id)                  -- composite PK = the pair
);

