package com.bank.rel;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class RelationshipDao {
    private static final Logger log = Logger.getLogger(RelationshipDao.class.getName());
    private final Connection conn;

    public RelationshipDao(Connection conn) { this.conn = conn; }

    // One-to-Many: all transactions for one account.
    public List<String> transactionsFor(String accountId) throws Exception {
        List<String> out = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(
                "SELECT txn_id FROM transactions WHERE account_id = ?")) {
            ps.setString(1, accountId);
            try (ResultSet rs = ps.executeQuery()) { while (rs.next()) out.add(rs.getString(1)); }
        }
        log.info(() -> accountId + " has " + out.size() + " transactions (one-to-many)");
        return out;
    }

    // One-to-One: the single KYC record for an account.
    public boolean isKycVerified(String accountId) throws Exception {
        try (PreparedStatement ps = conn.prepareStatement(
                "SELECT verified FROM account_kyc WHERE account_id = ?")) {
            ps.setString(1, accountId);
            try (ResultSet rs = ps.executeQuery()) { return rs.next() && rs.getBoolean(1); }
        }
    }

    // Many-to-Many: all products a customer holds (join through the junction table).
    public List<String> productsOf(long customerId) throws Exception {
        List<String> out = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(
                "SELECT p.name FROM holdings h JOIN products p ON p.product_id = h.product_id "
              + "WHERE h.customer_id = ?")) {
            ps.setLong(1, customerId);
            try (ResultSet rs = ps.executeQuery()) { while (rs.next()) out.add(rs.getString(1)); }
        }
        log.info(() -> "Customer " + customerId + " holds " + out + " (many-to-many)");
        return out;
    }
}
