package com.bank.rel;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.logging.Logger;

public class RelationshipDemo {
    private static final Logger log = Logger.getLogger(RelationshipDemo.class.getName());

    public static void main(String[] args) throws Exception {
        try (Connection conn = DriverManager.getConnection(
                "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret")) {
            RelationshipDao dao = new RelationshipDao(conn);

            dao.transactionsFor("SAV2001");               // one-to-many
            log.info(() -> "SAV2001 KYC verified? " + dao.isKycVerified("SAV2001")); // one-to-one
            dao.productsOf(1);                             // many-to-many (Rajesh: Savings, Credit Card)
            dao.productsOf(2);                             // many-to-many (Priya: Savings, Home Loan)
        }
    }
}
